package sn.ucad.nexora.espace.infrastructure.security.jwt;
import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import io.jsonwebtoken.Claims; import io.jsonwebtoken.Jwts; import io.jsonwebtoken.io.Decoders; import io.jsonwebtoken.security.Keys;
@Component public class JwtProviderAdapter{private final SecretKey key;public JwtProviderAdapter(@Value("${jwt.secret}") String secret){key=Keys.hmacShaKeyFor(Decoders.BASE64.decode(secret));}public Claims parseToken(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();}}
